import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

export interface Job {
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  db.exec(`PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL,
      steps INTEGER NOT NULL, fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result_output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, next_attempt_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_queue_idx ON jobs(status, next_attempt_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (
      key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id)
    );
    CREATE TABLE IF NOT EXISTS worker_heartbeat (id INTEGER PRIMARY KEY CHECK (id=1), seen_at INTEGER NOT NULL);`);
  return db;
}

export function toJob(row: any): Job {
  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps,
    failAttempts: row.fail_attempts, attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.result_output === null ? null : { output: row.result_output },
    error: row.error, createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

export const jobSelect = 'SELECT * FROM jobs';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, jobSelect } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}
function error(res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void {
  const info: Record<string, unknown> = { code, message };
  if (fields) info.fields = fields;
  send(res, status, { error: info });
}
async function bodyText(req: IncomingMessage): Promise<string> {
  let body = '';
  for await (const chunk of req) {
    body += chunk.toString();
    if (body.length > 1_000_000) throw new Error('body_too_large');
  }
  return body;
}
function validate(value: unknown): {input:string;steps:number;failAttempts:number} | {fields:{field:string;message:string}[]} {
  const fields: {field:string;message:string}[] = [];
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return { fields: [{ field: 'body', message: 'Must be a JSON object.' }] };
  }
  const obj = value as Record<string, unknown>;
  for (const key of Object.keys(obj)) if (!['input','steps','failAttempts'].includes(key)) fields.push({field:key,message:'Unknown field.'});
  if (typeof obj.input !== 'string') fields.push({field:'input',message:'Must be a string.'});
  else {
    if (obj.input.length < 1 || obj.input.length > 1000) fields.push({field:'input',message:'Must be 1 to 1000 characters.'});
    if (obj.input.trim().length === 0) fields.push({field:'input',message:'Must not be only whitespace.'});
  }
  let steps: unknown = obj.steps === undefined ? 5 : obj.steps;
  let failAttempts: unknown = obj.failAttempts === undefined ? 0 : obj.failAttempts;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({field:'steps',message:'Must be an integer from 1 to 20.'});
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({field:'failAttempts',message:'Must be an integer from 0 to 5.'});
  if (fields.length) return { fields };
  return { input: obj.input as string, steps: steps as number, failAttempts: failAttempts as number };
}

const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  if (pathname === '/' && req.method === 'GET') {
    res.writeHead(200, {'content-type':'text/html; charset=utf-8'}); res.end(uiHtml); return;
  }
  if (pathname === '/') return error(res,405,'method_not_allowed','Method not allowed.');
  if (pathname === '/health') {
    if (req.method !== 'GET') return error(res,405,'method_not_allowed','Method not allowed.');
    const heartbeat = db.prepare('SELECT seen_at FROM worker_heartbeat WHERE id=1').get() as {seen_at:number}|undefined;
    return send(res,200,{status:'ok',worker:heartbeat && Date.now()-heartbeat.seen_at <= 3000 ? 'up':'down'});
  }
  if (pathname === '/api/jobs' && req.method === 'GET') {
    const rows = db.prepare(`${jobSelect} ORDER BY created_at DESC, rowid DESC`).all();
    return send(res,200,{jobs:rows.map(toJob)});
  }
  if (pathname === '/api/jobs' && req.method === 'POST') {
    const contentType = req.headers['content-type'] ?? '';
    if (!/^application\/json(?:\s*;|\s*$)/i.test(contentType)) return error(res,400,'invalid_request','Invalid request.',[{field:'Content-Type',message:'Must be application/json.'}]);
    const rawKey = req.headers['idempotency-key'];
    const key = Array.isArray(rawKey) ? rawKey[0] : rawKey;
    if (key !== undefined && !/^[A-Za-z0-9_-]{1,128}$/.test(key)) return error(res,400,'invalid_request','Invalid request.',[{field:'Idempotency-Key',message:'Must contain 1 to 128 letters, digits, underscores, or hyphens.'}]);
    let parsed: unknown;
    try { const raw = await bodyText(req); parsed = JSON.parse(raw); }
    catch { return error(res,400,'invalid_request','Invalid request.',[{field:'body',message:'Must contain valid JSON.'}]); }
    const checked = validate(parsed);
    if ('fields' in checked) return error(res,400,'invalid_request','Invalid request.',checked.fields);
    const payload = JSON.stringify(checked);
    db.exec('BEGIN IMMEDIATE');
    try {
      if (key !== undefined) {
        const prior = db.prepare('SELECT payload,job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string}|undefined;
        if (prior) {
          db.exec('COMMIT');
          if (prior.payload !== payload) return error(res,409,'idempotency_conflict','This Idempotency-Key was already used with a different payload.');
          const existing = db.prepare(`${jobSelect} WHERE id=?`).get(prior.job_id);
          return send(res,200,toJob(existing));
        }
      }
      const id = randomUUID(); const now = new Date().toISOString();
      db.prepare(`INSERT INTO jobs(id,status,input,steps,fail_attempts,attempts,progress_completed,result_output,error,created_at,updated_at,next_attempt_at)
        VALUES(?,?,?,?,?,0,0,NULL,NULL,?,?,0)`).run(id,'queued',checked.input,checked.steps,checked.failAttempts,now,now);
      if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key,payload,id);
      const row = db.prepare(`${jobSelect} WHERE id=?`).get(id);
      db.exec('COMMIT');
      return send(res,201,toJob(row));
    } catch (e) { db.exec('ROLLBACK'); throw e; }
  }
  const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
  if (match) {
    if (req.method !== 'GET') return error(res,405,'method_not_allowed','Method not allowed.');
    let id: string; try { id = decodeURIComponent(match[1]); } catch { return error(res,404,'not_found','Job not found.'); }
    const row = db.prepare(`${jobSelect} WHERE id=?`).get(id);
    return row ? send(res,200,toJob(row)) : error(res,404,'not_found','Job not found.');
  }
  if (pathname === '/api/jobs') return error(res,405,'method_not_allowed','Method not allowed.');
  return error(res,404,'not_found','Not found.');
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));
let stopping = false;
for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => {
  if (stopping) return; stopping = true;
  server.close(() => { db.close(); process.exit(0); });
});
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';

const db = openDatabase();
let stopping = false;
let activeId: string | null = null;

// A running row can only belong to a worker that is no longer processing it after
// this process starts. Requeue it so an interrupted attempt is safely restarted.
db.prepare("UPDATE jobs SET status='queued', progress_completed=0, updated_at=? WHERE status='running'").run(new Date().toISOString());
const heartbeat = () => db.prepare(`INSERT INTO worker_heartbeat(id,seen_at) VALUES(1,?)
  ON CONFLICT(id) DO UPDATE SET seen_at=excluded.seen_at`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 500);

for (const signal of ['SIGINT','SIGTERM'] as const) process.on(signal, () => { stopping = true; });

function claim(): any | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare("SELECT * FROM jobs WHERE status='queued' AND next_attempt_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as any;
    if (!row) { db.exec('COMMIT'); return undefined; }
    const now = new Date().toISOString();
    db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(now,row.id);
    const claimed = db.prepare('SELECT * FROM jobs WHERE id=?').get(row.id);
    db.exec('COMMIT'); return claimed;
  } catch (e) { db.exec('ROLLBACK'); throw e; }
}

async function processJob(job: any): Promise<void> {
  activeId = job.id;
  const attempt = job.attempts;
  if (attempt <= job.fail_attempts) {
    if (!stopping) await sleep(100);
    if (stopping) return;
    const now = new Date().toISOString();
    if (attempt >= 3) {
      db.prepare("UPDATE jobs SET status='failed', progress_completed=0, result_output=NULL, error='transient failure', updated_at=? WHERE id=? AND status='running'").run(now,job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', progress_completed=0, next_attempt_at=?, updated_at=? WHERE id=? AND status='running'").run(Date.now()+500,now,job.id);
    }
    activeId = null; return;
  }
  for (let step=1; step<=job.steps; step++) {
    await sleep(100);
    if (stopping) return;
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step,new Date().toISOString(),job.id);
  }
  db.prepare("UPDATE jobs SET status='completed', progress_completed=steps, result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'")
    .run(String(job.input).toUpperCase(),new Date().toISOString(),job.id);
  activeId = null;
}

console.log('worker started');
try {
  while (!stopping) {
    heartbeat();
    const job = claim();
    if (job) await processJob(job);
    else await sleep(100);
  }
} finally {
  clearInterval(heartbeatTimer);
  if (activeId) db.prepare("UPDATE jobs SET status='queued', progress_completed=0, next_attempt_at=0, updated_at=? WHERE id=? AND status='running'").run(new Date().toISOString(),activeId);
  db.close();
}
