<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form">
    <label>Input <input data-testid="job-input" name="input" required maxlength="1000"></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" min="1" max="20" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorRegion = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    const esc = (value) => String(value ?? '');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
        const title = document.createElement('strong'); title.textContent = job.input;
        const status = document.createElement('div'); status.dataset.testid = 'job-status'; status.textContent = job.status;
        const progress = document.createElement('div'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result ? job.result.output : job.error || '';
        const attempts = document.createElement('small'); attempts.textContent = `Attempts: ${job.attempts}`;
        item.append(title,status,progress,result,attempts); return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); }
      catch (_) { /* The next poll will retry when the server is reachable. */ }
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorRegion.textContent = '';
      const data = new FormData(form);
      const payload = { input: data.get('input'), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
      try {
        const response = await fetch('/api/jobs', { method:'POST', headers:{'content-type':'application/json'}, body:JSON.stringify(payload) });
        const body = await response.json();
        if (!response.ok) {
          const detail = body.error || {};
          const fields = (detail.fields || []).map(field => `${field.field}: ${field.message}`);
          errorRegion.textContent = [detail.message || 'Request rejected.', ...fields].join(' ');
          return;
        }
        form.elements.input.value = '';
        await refresh();
      } catch (_) { errorRegion.textContent = 'Unable to submit the job. Please try again.'; }
    });
    refresh(); setInterval(refresh, 750);
  </script>
</body>
